// Example: retrieving a value from a map with type safety
class Registry {
    private items = new Map<string, any>();

    getItem(key: string): any {
        const item = this.items.get(key);
        if (!item) {
            throw new Error(`Item '${key}' not found`);
        }
        return item;
    }
}

